import dtk;
import log;
var paraMap = {};
paraMap.url = "/api/category/ddq-goods-list";
paraMap.tmall = "1";
paraMap.haitao = "1";
if (body && body.roundTime) {
    paraMap.roundTime = body.roundTime;
}

var raw = dtk.execute(paraMap);
var rawData = (raw && raw.data) ? raw.data : {};

var result = {};
result.ddqTime = rawData && rawData.ddqTime ? rawData.ddqTime : "";
result.goodsList = (rawData && rawData.goodsList) ? rawData.goodsList : [];
result.roundsList = (rawData && rawData.roundsList) ? rawData.roundsList : [];
result.status = (rawData && rawData.status != null) ? rawData.status : 0;
return result;


